function Choice({value,onChange,options,label}:{value:string,onChange:(v:string)=>void,options:string[],label:string}){return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} className="m-choice"><SelectValue/></SelectTrigger><SelectContent className="m-options">{options.map(o=><SelectItem key={o} value={o}>{o}</SelectItem>)}</SelectContent></Select>}
function Field({label,children,hint}:{label:string,children:ReactNode,hint?:string}){return <label className="m-field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Toggle({title,detail,value,onChange}:{title:string,detail:string,value:boolean,onChange:(v:boolean)=>void}){return <div className="m-toggle"><div><strong>{title}</strong><p>{detail}</p></div><Switch aria-label={title} checked={value} onCheckedChange={onChange}/></div>}
function Tag({children,tone=''}:{children:ReactNode,tone?:string}){return <span className={`m-tag ${tone}`}>{children}</span>}
function Empty({title,text,action}:{title:string,text:string,action?:ReactNode}){return <div className="m-empty"><Heart size={28}/><h3>{title}</h3><p>{text}</p>{action}</div>}
function Portrait({p,locked=false,small=false}:{p:Member,locked?:boolean,small?:boolean}){return locked?<div className={`m-portrait m-photo-private ${small?'m-small':''}`}><LockKeyhole size={small?20:30}/>{!small&&<><strong>A little privacy, by choice.</strong><span>Photo shared with permission</span></>}</div>:<div role="img" aria-label={`${p.name} — fictional member`} className={`m-portrait ${small?'m-small':''}`} style={{backgroundImage:p.photoKey?`url(${p.photoKey})`:PORTRAIT_BG,backgroundSize:p.photoKey?'cover':'300% 200%',backgroundPosition:p.photoKey?'center':`${p.photo%3*50}% ${p.photo<3?0:100}%`}}/>}
