function ContextFields({value,country,onChange}:{value:any,country:string,onChange:(v:any)=>void}){const c={...blankContext(),...value};return <><HelpNote>Optional, candidate-declared details. Saved answers appear on your public member profile. Leave anything you prefer not to share blank.</HelpNote><div className="m-form-grid"><Field label={country==='Sri Lanka'?'District':country==='India'?'State / union territory':'Region'}>{['Sri Lanka','India'].includes(country)?<Choice label="Your region" value={c.region||'Not shared'} options={['Not shared',...(country==='Sri Lanka'?districts:indianRegions)]} onChange={v=>onChange({...c,region:v==='Not shared'?'':v})}/>:<input value={c.region} onChange={e=>onChange({...c,region:e.target.value})} maxLength={80}/>}</Field>{Object.entries(contextOptions).map(([key,options])=><Field key={key} label={contextLabels[key]}><Choice label={'Your '+contextLabels[key]} value={c[key]||'Not shared'} options={['Not shared',...options]} onChange={v=>onChange({...c,[key]:v==='Not shared'?'':v})}/></Field>)}<Field label="Caste / community (optional)" hint="Self-described only. Never inferred from your name or photo."><input value={c.caste} maxLength={80} placeholder="Leave blank if not shared" onChange={e=>onChange({...c,caste:e.target.value})}/></Field></div></>}
function Brand(){return <a className="m-brand" href="#" onClick={e=>{e.preventDefault();window.openFavoriteLanding()}} aria-label="Favorite Hearts landing page"><span><Heart size={19} fill="currentColor"/></span>Favorite Hearts<span className="m-brand-dot">.</span></a>}

