 const [connectionTab,setConnectionTab]=useState('received'),[adminTab,setAdminTab]=useState('payments'),[report,setReport]=useState<Member|null>(null),[reason,setReason]=useState('Suspicious profile or scam'),[reportText,setReportText]=useState('');
 const [confirm,setConfirm]=useState<{title:string,text:string,action:any}|null>(null),[uploadKind,setUploadKind]=useState<'selfie'|'photo'|'gallery'|null>(null),[file,setFile]=useState<File|null>(null);
 const [checkout,setCheckout]=useState<string|null>(null),[reference,setReference]=useState(''),[review,setReview]=useState<any>(null),[reviewNote,setReviewNote]=useState(''),[message,setMessage]=useState('');
