 useEffect(()=>{if(detail||filterOpen||uploadKind||checkout||review||report||birth||confirm||deleteOpen||compareOpen||contextDraft)document.querySelector('#favorite-hearts-product > .m-app')?.scrollTo({top:0})},[detail,filterOpen,uploadKind,checkout,review,report,birth,confirm,deleteOpen,compareOpen,contextDraft]);
 async function refresh(who=actor){setError('');try{const d:any=viewNetwork(window.__heartsNetwork||(window.__heartsNetwork=initialNetwork()),who,seat);setS(d);setPrefs({...defaultPreferences(),...d.preferences});if(!d.onboarded){setDraft(d.draft||blankProfile());setOnboarding(true)}}catch(e){setError(e instanceof Error?e.message:'Could not open Matrimony.')}}
 useEffect(()=>{setDetail(null);setConfirm(null);refresh()},[actor,seat]);
 useEffect(()=>{if(s?.candidateRestricted&&!['trust','membership','contact'].includes(page)){setPage('trust');setOnboarding(false);setDetail(null);setBirth(null)}},[s?.candidateRestricted,page]);
 useEffect(()=>{if(s){setDetail(d=>d?s.directory.find(p=>p.id===d.id)||null:null);setCompare(ids=>ids.filter(id=>s.directory.some(p=>p.id===id)&&!['declined','ended'].includes(s.interests[id])));}},[s]);
 async function act(a:any,success?:string){a={...a,seat};setBusy(true);try{window.__heartsNetwork=applyNetwork(window.__heartsNetwork,actor,a);const d:any=viewNetwork(window.__heartsNetwork,actor,seat);setS(d);if(success)toast.success(success);return d as NetworkView}catch(e){toast.error(e instanceof Error?e.message:'Please try again.');return null}finally{setBusy(false)}}
 async function upload(kind:string){if(!file){toast.error('Choose a sample file first.');return}setBusy(true);try{if(file.size>5*1024*1024)throw new Error('Maximum file size is 5 MB.');if(!(kind==='payment'?['application/pdf','image/jpeg','image/png']:['image/jpeg','image/png']).includes(file.type))throw new Error('Choose a supported file.');const key=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)});const network=structuredClone(window.__heartsNetwork),d=network.accounts[actor];requirePermission(d,{type:kind==='payment'?'payment':kind==='selfie'?'verificationSubmit':'photoUpload'},seatFor(d,seat));if(kind==='payment'){if(d.payments.some(p=>p.status==='pending'))throw new Error('A payment is already awaiting review.');if(reference.trim().length<3)throw new Error('Add a transfer reference.');const p=memberships.find(p=>p.id===checkout)!;if(p.id==='boost')validateBoostPurchase(d,seatFor(d,seat));if(p.id==='ownership-transfer'&&(seat!=='candidate'||d.ownershipTransfer?.status!=='requested'))throw new Error('Request ownership as the candidate first.');if(d.me.role!=='Self'&&seat==='candidate'&&p.id!=='ownership-transfer')throw new Error('Choose ownership transfer.');d.payments.unshift({id:crypto.randomUUID(),plan:p.id,amount:p.price,reference,key,name:file.name,type:file.type,status:'pending',at:new Date().toISOString(),note:''})}else if(kind==='selfie'){d.verification={status:'pending',key,note:''}}else if(kind==='gallery'){if((d.gallery||[]).length>=4)throw new Error('Up to four private gallery photos plus one cover.');d.gallery=[...(d.gallery||[]),{key,name:file.name,at:new Date().toISOString()}]}else d.photo={key,name:file.name,at:new Date().toISOString()};window.__heartsNetwork=network;setS(viewNetwork(network,actor,seat));setFile(null);setCheckout(null);setUploadKind(null);toast.success(kind==='payment'?'Sample payment proof is awaiting review.':kind==='selfie'?'Sample selfie submitted for review.':'Photo added to this preview.')}catch(e){toast.error(e instanceof Error?e.message:'Please try again.')}finally{setBusy(false)}}

 function go(p:string){if(p==='boost'){if(s?.candidateRestricted)return;setBoostOpen(true);setMobile(false);return;}if(s?.candidateRestricted&&!['trust','membership','contact'].includes(p))return;if((p==='connected'&&!s?.paid)||(p==='interests'&&!s?.paid&&!s?.publisherVerified)){toast('Activate membership to use interests and mutual connections.');setMobile(false);return;}if(p==='connected')setConnectionTab('mutual');if(p==='interests')setConnectionTab('received');if(p==='admin')setSeat('reviewer');else if(seat==='reviewer')setSeat(s?.ownershipTransfer?.status==='approved'?'candidate':'manager');setPage(p);setMobile(false);setDetail(null);setOnboarding(false);document.querySelector('#favorite-hearts-product > .m-app')?.scrollTo({top:0,behavior:'smooth'});}
 function edit(){setDraft(s?.draft|| (s?.onboarded?{...s.me}:blankProfile()));setStep(s?.onboarded?1:0);setFormError('');setOnboarding(true);setMobile(false)}
