  if(step===2&&draft.bio.trim().length<20)err='Write at least 20 characters about the candidate.';
  if(step===4&&!draft.agreement)err='Confirm the adult candidate’s eligibility and your authority to publish.';
  if(step===3&&(!/^\+?[0-9]{9,15}$/.test((draft.contactPhone??s?.contact.phone??'').replace(/[\s()-]/g,''))||!(draft.sharingAccepted??s?.sharingAccepted)))err='Add a private phone number and confirm sharing after mutual acceptance.';
  if(err){setFormError(err);return}
  if(step===3){const saved=await act({type:'contact',email:draft.contactEmail??s?.contact.email,phone:draft.contactPhone??s?.contact.phone,sharingAccepted:draft.sharingAccepted??s?.sharingAccepted});if(!saved)return;}
