 const Card=({p}:{p:Member})=><article className={`m-card ${p.featured?'m-featured-card':p.boosted?'m-boosted-card':''}`}><>{(p.featured||p.boosted)&&<div className="m-promotion-label">{p.featured?<><Crown size={17}/>Featured</>:<><Zap size={17}/>Boosted</>}{p.featured&&p.boosted&&<span> · Boost active</span>}</div>}</><div className="m-card-identity"><button className="m-card-photo" onClick={()=>openDetail(p)} aria-label={`View ${p.name}'s profile`}><Portrait p={p} locked={locked(p)}/><div className="m-photo-top"><Tag tone="white">{p.verified?<><ShieldCheck size={14}/>Selfie reviewed</>:<><Clock size={14}/>Not yet verified</>}</Tag></div>{s?.interests[p.id]==='received'&&<span className="m-photo-interest"><Heart size={13} fill="currentColor"/>Interested in you</span>}</button><div className="m-card-identity-copy"><div className="m-card-title"><button onClick={()=>openDetail(p)}>{p.name}<span>, {p.age}</span></button></div><p className="m-location"><MapPin size={14}/>{p.city}, {p.country}</p><p className="m-profession"><BriefcaseBusiness size={15}/>{p.job}</p></div><button className={`m-bookmark ${s?.saved.includes(p.id)?'is-saved':''}`} aria-label={`${s?.saved.includes(p.id)?'Unsave':'Save'} ${p.name}`} onClick={()=>save(p)}><Bookmark size={18} fill={s?.saved.includes(p.id)?'currentColor':'none'}/></button></div><div className="m-card-body"><div className="m-card-meta"><span className={`m-activity ${p.activity==='Online'?'is-online':'is-offline'}`} title={p.activityDemo?'Simulated activity for this sample profile':undefined}>{p.activity==='Online'?<><i className="m-online-dot" aria-hidden="true"/><small>Online</small></>:<small>{p.activity}</small>}</span><button className="m-score-button" aria-label={`View compatibility with ${p.name}`} title="Shared-values compatibility" onClick={()=>setCompatibilityProfile(p)}><svg viewBox="0 0 24 24" width="20" height="20" fill="none" aria-hidden="true"><circle cx="9" cy="12" r="6" stroke="currentColor" strokeWidth="1.7"/><circle cx="15" cy="12" r="6" stroke="currentColor" strokeWidth="1.7"/><path d="M12 7.6a6 6 0 0 1 0 8.8 6 6 0 0 1 0-8.8Z" fill="currentColor" opacity=".2"/></svg></button></div><div className="m-role"><Users size={14}/>{p.role}{p.verified&&<span> · Selfie reviewed</span>}{s?.interests[p.id]==='received'&&<span> · Interested in you</span>}</div><TrustBadges badges={p.trustBadges}/><div className="m-values">{p.values.slice(0,2).map(v=><span key={v}>{v}</span>)}<span>{p.intent==='Ready for marriage'?'Ready for marriage':'Marriage-minded'}</span></div><div className="m-common">{sharedValues(p).length>0?<><Sparkles size={13}/>Shared: {sharedValues(p).slice(0,2).join(' · ')}</>:<><LockKeyhole size={13}/>{p.shared?'Private details shared':'Private until mutual acceptance'}</>}</div><div className="m-card-actions"><button className="m-btn m-secondary" onClick={()=>openDetail(p)}>View profile</button><button className="m-btn" disabled={busy||(!!s?.interests[p.id]&&s?.interests[p.id]!=='received')} onClick={()=>s?.interests[p.id]==='received'?acceptInterest(p):sendInterest(p)}><Heart size={15}/>{s?.interests[p.id]==='received'?'Accept interest':actionLabel(p.id)}</button></div><label className="m-compare-pick"><input type="checkbox" checked={compare.includes(p.id)} onChange={()=>toggleCompare(p.id)}/>Compare profile</label></div></article>;
 const row=(p:Member,actions:ReactNode)=><article className="m-person-row" key={p.id}><button className="m-avatar-button" onClick={()=>openDetail(p)}><Portrait p={p} small locked={locked(p)}/></button><div className="m-row-copy"><button className="m-name-link" onClick={()=>openDetail(p)}>{p.name}, {p.age}</button><p className="m-row-facts"><span><BriefcaseBusiness size={14}/>{p.job}</span><span><MapPin size={14}/>{p.city}</span></p><small>{p.role}</small></div><div className="m-row-actions">{actions}</div></article>;
